VID = {1: 'o3eT4Ipg67E', 2: '29WK_-5cpOQ', 3: 'YNTpIQ-cENk'}
def yt(s, tc):
    p = [int(x) for x in tc.split(':')]
    while len(p) < 3: p = [0] + p
    sec = p[0]*3600 + p[1]*60 + p[2]
    return {'t': f'стрим {s} · {tc}', 'u': f'https://youtu.be/{VID[s]}?t={sec}'}
def ext(t, u): return {'t': t, 'u': u}

